    try:
        # Read the temperature data from the AMG8833
        data = bus.read_i2c_block_data(I2C_ADDRESS, 0x80, 16)
        temperatures = []
        for i in range(0, len(data), 2):
            temp = (data[i] << 8) | data[i + 1]
            temperatures.append((temp / 32.0) - 273.15)
        return temperatures
    except Exception as e:
        print(f"Error reading from AMG8833: {e}")
        return None

def main():
    try:
        bus = smbus2.SMBus(I2C_PORT)
        while True:
            temps = read_amg8833_temperature(bus)
            if temps is not None:
                print("Temperatures:", temps)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        bus.close()
        print("Hardware resources released.")

