def read_mpu6050(bus, address):
    try:
        # Read accelerometer data
        accel_x = bus.read_word_data(address, 0x3B)
        accel_y = bus.read_word_data(address, 0x3D)
        accel_z = bus.read_word_data(address, 0x3F)

        # Read gyroscope data
        gyro_x = bus.read_word_data(address, 0x43)
        gyro_y = bus.read_word_data(address, 0x45)
        gyro_z = bus.read_word_data(address, 0x47)

        return {
            'accel': {'x': accel_x, 'y': accel_y, 'z': accel_z},
            'gyro': {'x': gyro_x, 'y': gyro_y, 'z': gyro_z}
        }
    except smbus2.SMBusError as e:
        print(f"Failed to read from MPU6050: {e}")
        return None

def main():
    i2c_address = 0x68
    bus = smbus2.SMBus(1)  # Use 1 for RPi 2/3, 0 for RPi 1

    try:
        mpu_data = read_mpu6050(bus, i2c_address)
        if mpu_data:
            print(f"Accel: X={mpu_data['accel']['x']}, Y={mpu_data['accel']['y']}, Z={mpu_data['accel']['z']}")
            print(f"Gyro: X={mpu_data['gyro']['x']}, Y={mpu_data['gyro']['y']}, Z={mpu_data['gyro']['z']}")
        else:
            raise Exception("MPU6050 not found or unresponsive")
    except Exception as e:
