class PCA9685(PWMDevice):
    def __init__(self, address=0x40, bus=None):
        super().__init__(frequency=50, pin_factory=None)
        self._address = address
        self._bus = bus or i2c_device.I2C.get_default_bus()
        try:
            self._bus.open(self._address)
        except OSError as e:
            print(f"Error: PCA9685 at address {self._address} not found.", file=sys.stderr)
            sys.exit(1)

    def close(self):
        if not self.closed:
            self._bus.close()
            super().close()

def signal_handler(sig, frame):
    print("Interrupted by user.")
    pca9685.close()
    sys.exit(0)

