import smbus2
import time

def read_amg8833_temp(bus, address):
    try:
        # Read the temperature data from the AMG8833
        temp_data = bus.read_i2c_block_data(address, 0x80, 16)
        # Convert the raw data to temperature values
        temps = [((temp_data[i] << 8) | temp_data[i+1]) / 16.0 for i in range(0, 16, 2)]
        return temps
    except smbus2.SMBusError as e:
        print(f"Failed to read from AMG8833: {e}")
        return None

def main():
    bus = smbus2.SMBus(1)  # Use I2C bus 1
    address = 0x69

    try:
        while True:
            temps = read_amg8833_temp(bus, address)
            if temps is not None:
                print("Temperatures:", temps)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nInterrupted by user")
    finally:
        bus.close()
        print("I2C bus released")

if __name__ == "__main__":
    main()
